<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { BriefcaseBusiness, CheckCircle2, Layers3, ShieldAlert, UsersRound } from 'lucide-vue-next'
import { RouterLink } from 'vue-router'
import WorkspaceFrame from '@/components/workspace/WorkspaceFrame.vue'
import { workspaceApi, type CompanyDashboardData } from '@/services/workspace'

const data = ref<CompanyDashboardData | null>(null)
const loading = ref(true)
const error = ref('')
const statusLabels: Record<string, string> = { DRAFT: 'Borrador', PUBLISHED: 'Publicada', PAUSED: 'Pausada', CLOSED: 'Cerrada', REMOVED: 'Retirada' }
const verificationLabels: Record<string, string> = { PENDING: 'Verificación pendiente', VERIFIED: 'Empresa verificada', REJECTED: 'Verificación rechazada' }
onMounted(async () => {
  try { data.value = await workspaceApi.companyDashboard() }
  catch (e) { error.value = e instanceof Error ? e.message : 'No se pudo cargar el panel de empresa.' }
  finally { loading.value = false }
})
</script>

<template>
  <WorkspaceFrame v-if="data" eyebrow="Espacio empresa" :title="data.company.name" :subtitle="[[data.company.municipality?.name, data.company.department?.name].filter(Boolean).join(', '), data.company.economicSector?.name, 'Administra tus ofertas y revisa las candidaturas recibidas.'].filter(Boolean).join(' · ')" :initials="data.company.name.slice(0, 2).toUpperCase()">
    <template #heading-action><RouterLink class="workspace__cta company-dashboard__create" to="/company/jobs/new"><span aria-hidden="true">＋</span> Crear vacante</RouterLink></template>
    <p v-if="error" class="workspace__error" role="alert">{{ error }}</p>
    <section class="company-dashboard__verification" :class="`company-dashboard__verification--${data.company.verificationStatus.toLowerCase()}`"><span class="company-dashboard__verification-mark"><CheckCircle2 v-if="data.company.verificationStatus === 'VERIFIED'" :size="17" /><ShieldAlert v-else :size="17" /></span><div><strong>{{ verificationLabels[data.company.verificationStatus] ?? data.company.verificationStatus }}</strong><p>{{ data.company.verificationStatus === 'VERIFIED' ? 'Tu empresa puede publicar vacantes y recibir postulaciones.' : 'Puedes preparar vacantes como borrador. La publicación requiere verificación de Jinowork.' }}</p></div><RouterLink to="/company/profile">Ver perfil <span aria-hidden="true">↗</span></RouterLink></section>
    <section class="workspace__grid company-dashboard__stats" aria-label="Resumen de empresa">
      <article class="workspace__card workspace__stat company-stat"><span class="company-stat__icon" aria-hidden="true"><BriefcaseBusiness :size="18" /></span><div class="workspace__stat-label">Vacantes publicadas</div><div class="workspace__stat-value">{{ data.stats.publishedJobs }}</div><RouterLink to="/company/jobs">Administrar vacantes <span aria-hidden="true">→</span></RouterLink></article>
      <article class="workspace__card workspace__stat company-stat"><span class="company-stat__icon" aria-hidden="true"><Layers3 :size="18" /></span><div class="workspace__stat-label">Vacantes totales</div><div class="workspace__stat-value">{{ data.stats.totalJobs }}</div><RouterLink to="/company/jobs">Ver todos los estados <span aria-hidden="true">→</span></RouterLink></article>
      <article class="workspace__card workspace__stat company-stat company-stat--accent"><span class="company-stat__icon" aria-hidden="true"><UsersRound :size="18" /></span><div class="workspace__stat-label">Postulaciones recibidas</div><div class="workspace__stat-value">{{ data.stats.totalApplications }}</div><RouterLink to="/company/applications">Revisar candidatos <span aria-hidden="true">→</span></RouterLink></article>
    </section>
    <section class="workspace__card workspace__section company-dashboard__jobs"><header class="company-dashboard__section-head"><div><span class="company-dashboard__kicker">Contratación</span><h2>Vacantes recientes</h2></div><RouterLink to="/company/jobs">Gestionar vacantes <span aria-hidden="true">→</span></RouterLink></header>
      <div v-if="data.recentJobs.length" class="company-dashboard__job-list"><article v-for="job in data.recentJobs" :key="job.id" class="company-dashboard__job"><span class="company-dashboard__job-mark">{{ job.title.slice(0,1).toUpperCase() }}</span><div class="company-dashboard__job-main"><RouterLink :to="`/company/jobs/${job.id}/edit`">{{ job.title }}</RouterLink><span>{{ job._count.applications }} postulaciones <i>·</i> {{ job._count.views }} vistas <i>·</i> {{ new Date(job.createdAt).toLocaleDateString('es-NI') }}</span></div><span class="workspace__pill" :class="`company-dashboard__status--${job.status.toLowerCase()}`">{{ statusLabels[job.status] ?? job.status }}</span><RouterLink class="company-dashboard__job-open" :to="{ path: '/company/applications', query: { jobId: job.id } }">Ver candidatos <span aria-hidden="true">↗</span></RouterLink></article></div>
      <div v-else class="company-dashboard__empty"><span aria-hidden="true">▤</span><strong>Aún no hay vacantes</strong><p>Cuando publiques una oferta, aquí podrás seguir su actividad y revisar a sus postulantes.</p><RouterLink to="/company/jobs">Ir a gestión de vacantes <span aria-hidden="true">→</span></RouterLink></div>
    </section>
    <div class="company-dashboard__footer-actions"><RouterLink to="/company/applications">Ver todas las postulaciones <span aria-hidden="true">→</span></RouterLink><RouterLink to="/company/profile">Editar perfil de empresa <span aria-hidden="true">→</span></RouterLink></div>
  </WorkspaceFrame>
  <main v-else class="workspace-loading"><p v-if="loading" role="status">Cargando tu panel…</p><p v-else class="workspace__error" role="alert">{{ error }}</p></main>
</template>

