ry);font-size:1.35rem}.company-dashboard__empty>strong{margin-top:.25rem}.company-dashboard__empty p{margin:0 0 .6rem;color:var(--muted-foreground);font-size:.8rem}.company-dashboard__footer-actions{display:flex;justify-content:flex-end;gap:1.2rem;flex-wrap:wrap;margin-top:1rem}.company-dashboard__footer-actions a{color:var(--primary);font-size:.78rem;font-weight:800}
@media(max-width:700px){.company-dashboard__stats{grid-template-columns:1fr}.company-dashboard__verification{align-items:flex-start;flex-wrap:wrap}.company-dashboard__verification>div{min-width:calc(100% - 3.5rem)}.company-dashboard__verification>a{margin-left:3.05rem}.company-dashboard__job{align-items:flex-start;flex-wrap:wrap}.company-dashboard__job-main{min-width:calc(100% - 3.5rem)}.company-dashboard__job>.workspace__pill{margin-left:3.4rem}.company-dashboard__job-open{margin-left:auto}}
